SELECT (SELECT COUNT(*) FROM trechos) AS trechos, (SELECT COUNT(DISTINCT publico || '|' || macronarrativa) FROM trechos WHERE tipo <> 'perfil') AS cruzamentos, (SELECT COUNT(*) FROM trechos WHERE tipo = 'perfil') AS perfil, (SELECT COUNT(*) FROM trechos WHERE tipo = 'achado' AND forca = 'forte') AS achados_forte, (SELECT COUNT(DISTINCT pauta) FROM trechos WHERE pauta IS NOT NULL) AS pautas_usadas, (SELECT COUNT(*) FROM paginas) AS paginas, (SELECT COUNT(*) FROM formatos) AS formatos;
